   221	static void readLine(QDataStream &s, QByteArray &buf, const PCXHEADER &header)
   222	{
   223	    quint32 i = 0;
   224	    quint32 size = buf.size();
   225	    quint8 byte, count;
   226	
   227	    if (header.isCompressed()) {
   228	        // Uncompress the image data
   229	        while (i < size) {
   230	            count = 1;
   231	            s >> byte;
   232	            if (byte > 0xc0) {
   233	                count = byte - 0xc0;
   234	                s >> byte;
   235	            }
   236	            while (count-- && i < size) {
   237	                buf[ i++ ] = byte;
   238	            }
   239	        }
   240	    } else {
   241	        // Image is not compressed (possible?)
   242	        while (i < size) {
   243	            s >> byte;
   244	            buf[ i++ ] = byte;
   245	        }
   246	    }
   247	}
