   249	static void readImage1(QImage &img, QDataStream &s, const PCXHEADER &header)
   250	{
   251	    QByteArray buf(header.BytesPerLine, 0);
   252	
   253	    img = QImage(header.width(), header.height(), QImage::Format_Mono);
   254	    img.setColorCount(2);
   255	
   256	    if (img.isNull())
   257	        return;
   258	
   259	    for (int y = 0; y < header.height(); ++y) {
   260	        if (s.atEnd()) {
   261	            img = QImage();
   262	            return;
   263	        }
   264	
   265	        readLine(s, buf, header);
   266	        uchar *p = img.scanLine(y);
   267	        unsigned int bpl = qMin((quint16)((header.width() + 7) / 8), header.BytesPerLine);
   268	        for (unsigned int x = 0; x < bpl; ++x) {
   269	            p[ x ] = buf[x];
   270	        }
   271	    }
   272	
   273	    // Set the color palette
   274	    img.setColor(0, qRgb(0, 0, 0));
   275	    img.setColor(1, qRgb(255, 255, 255));
   276	}
