   278	static void readImage4(QImage &img, QDataStream &s, const PCXHEADER &header)
   279	{
   280	    QByteArray buf(header.BytesPerLine * 4, 0);
   281	    QByteArray pixbuf(header.width(), 0);
   282	
   283	    img = QImage(header.width(), header.height(), QImage::Format_Indexed8);
   284	    img.setColorCount(16);
   285	
   286	    for (int y = 0; y < header.height(); ++y) {
   287	        if (s.atEnd()) {
   288	            img = QImage();
   289	            return;
   290	        }
   291	
   292	        pixbuf.fill(0);
   293	        readLine(s, buf, header);
   294	
   295	        for (int i = 0; i < 4; i++) {
   296	            quint32 offset = i * header.BytesPerLine;
   297	            for (int x = 0; x < header.width(); ++x)
   298	                if (buf[ offset + (x / 8) ] & (128 >> (x % 8))) {
   299	                    pixbuf[ x ] = (int)(pixbuf[ x ]) + (1 << i);
   300	                }
   301	        }
   302	
   303	        uchar *p = img.scanLine(y);
   304	        for (int x = 0; x < header.width(); ++x) {
   305	            p[ x ] = pixbuf[ x ];
   306	        }
   307	    }
   308	
   309	    // Read the palette
   310	    for (int i = 0; i < 16; ++i) {
   311	        img.setColor(i, header.ColorMap.color(i));
   312	    }
   313	}
