   315	static void readImage8(QImage &img, QDataStream &s, const PCXHEADER &header)
   316	{
   317	    QByteArray buf(header.BytesPerLine, 0);
   318	
   319	    img = QImage(header.width(), header.height(), QImage::Format_Indexed8);
   320	    img.setColorCount(256);
   321	
   322	    for (int y = 0; y < header.height(); ++y) {
   323	        if (s.atEnd()) {
   324	            img = QImage();
   325	            return;
   326	        }
   327	
   328	        readLine(s, buf, header);
   329	
   330	        uchar *p = img.scanLine(y);
   331	
   332	        if (!p)
   333	            return;
   334	
   335	        unsigned int bpl = qMin(header.BytesPerLine, (quint16)header.width());
   336	        for (unsigned int x = 0; x < bpl; ++x) {
   337	            p[ x ] = buf[ x ];
   338	        }
   339	    }
   340	
   341	    quint8 flag;
   342	    s >> flag;
   343	//   qDebug() << "Palette Flag: " << flag;
   344	
   345	    if (flag == 12 && (header.Version == 5 || header.Version == 2)) {
   346	        // Read the palette
   347	        quint8 r, g, b;
   348	        for (int i = 0; i < 256; ++i) {
   349	            s >> r >> g >> b;
   350	            img.setColor(i, qRgb(r, g, b));
   351	        }
   352	    }
   353	}
