   355	static void readImage24(QImage &img, QDataStream &s, const PCXHEADER &header)
   356	{
   357	    QByteArray r_buf(header.BytesPerLine, 0);
   358	    QByteArray g_buf(header.BytesPerLine, 0);
   359	    QByteArray b_buf(header.BytesPerLine, 0);
   360	
   361	    img = QImage(header.width(), header.height(), QImage::Format_RGB32);
   362	
   363	    for (int y = 0; y < header.height(); ++y) {
   364	        if (s.atEnd()) {
   365	            img = QImage();
   366	            return;
   367	        }
   368	
   369	        readLine(s, r_buf, header);
   370	        readLine(s, g_buf, header);
   371	        readLine(s, b_buf, header);
   372	
   373	        uint *p = (uint *)img.scanLine(y);
   374	        for (int x = 0; x < header.width(); ++x) {
   375	            p[ x ] = qRgb(r_buf[ x ], g_buf[ x ], b_buf[ x ]);
   376	        }
   377	    }
