   380	static void writeLine(QDataStream &s, QByteArray &buf)
   381	{
   382	    quint32 i = 0;
   383	    quint32 size = buf.size();
   384	    quint8 count, data;
   385	    char byte;
   386	
   387	    while (i < size) {
   388	        count = 1;
   389	        byte = buf[ i++ ];
   390	
   391	        while ((i < size) && (byte == buf[ i ]) && (count < 63)) {
   392	            ++i;
   393	            ++count;
   394	        }
   395	
   396	        data = byte;
   397	
   398	        if (count > 1 || data >= 0xc0) {
   399	            count |= 0xc0;
   400	            s << count;
   401	        }
   402	
   403	        s << data;
   404	    }
   405	}
