   407	static void writeImage1(QImage &img, QDataStream &s, PCXHEADER &header)
   408	{
   409	    img = img.convertToFormat(QImage::Format_Mono);
   410	
   411	    header.Bpp = 1;
   412	    header.NPlanes = 1;
   413	    header.BytesPerLine = img.bytesPerLine();
   414	
   415	    s << header;
   416	
   417	    QByteArray buf(header.BytesPerLine, 0);
   418	
   419	    for (int y = 0; y < header.height(); ++y) {
   420	        quint8 *p = img.scanLine(y);
   421	
   422	        // Invert as QImage uses reverse palette for monochrome images?
   423	        for (int i = 0; i < header.BytesPerLine; ++i) {
   424	            buf[ i ] = ~p[ i ];
   425	        }
   426	
   427	        writeLine(s, buf);
   428	    }
   429	}
