   431	static void writeImage4(QImage &img, QDataStream &s, PCXHEADER &header)
   432	{
   433	    header.Bpp = 1;
   434	    header.NPlanes = 4;
   435	    header.BytesPerLine = header.width() / 8;
   436	
   437	    for (int i = 0; i < 16; ++i) {
   438	        header.ColorMap.setColor(i, img.color(i));
   439	    }
   440	
   441	    s << header;
   442	
   443	    QByteArray buf[ 4 ];
   444	
   445	    for (int i = 0; i < 4; ++i) {
   446	        buf[ i ].resize(header.BytesPerLine);
   447	    }
   448	
   449	    for (int y = 0; y < header.height(); ++y) {
   450	        quint8 *p = img.scanLine(y);
   451	
   452	        for (int i = 0; i < 4; ++i) {
   453	            buf[ i ].fill(0);
   454	        }
   455	
   456	        for (int x = 0; x < header.width(); ++x) {
   457	            for (int i = 0; i < 4; ++i)
   458	                if (*(p + x) & (1 << i)) {
   459	                    buf[ i ][ x / 8 ] = (int)(buf[ i ][ x / 8 ]) | 1 << (7 - x % 8);
   460	                }
   461	        }
   462	
   463	        for (int i = 0; i < 4; ++i) {
   464	            writeLine(s, buf[ i ]);
   465	        }
   466	    }
   467	}
