   469	static void writeImage8(QImage &img, QDataStream &s, PCXHEADER &header)
   470	{
   471	    header.Bpp = 8;
   472	    header.NPlanes = 1;
   473	    header.BytesPerLine = img.bytesPerLine();
   474	
   475	    s << header;
   476	
   477	    QByteArray buf(header.BytesPerLine, 0);
   478	
   479	    for (int y = 0; y < header.height(); ++y) {
   480	        quint8 *p = img.scanLine(y);
   481	
   482	        for (int i = 0; i < header.BytesPerLine; ++i) {
   483	            buf[ i ] = p[ i ];
   484	        }
   485	
   486	        writeLine(s, buf);
   487	    }
   488	
   489	    // Write palette flag
   490	    quint8 byte = 12;
   491	    s << byte;
   492	
   493	    // Write palette
   494	    for (int i = 0; i < 256; ++i) {
   495	        s << RGB::from(img.color(i));
   496	    }
   497	}
