   499	static void writeImage24(QImage &img, QDataStream &s, PCXHEADER &header)
   500	{
   501	    header.Bpp = 8;
   502	    header.NPlanes = 3;
   503	    header.BytesPerLine = header.width();
   504	
   505	    s << header;
   506	
   507	    QByteArray r_buf(header.width(), 0);
   508	    QByteArray g_buf(header.width(), 0);
   509	    QByteArray b_buf(header.width(), 0);
   510	
   511	    for (int y = 0; y < header.height(); ++y) {
   512	        uint *p = (uint *)img.scanLine(y);
   513	
   514	        for (int x = 0; x < header.width(); ++x) {
   515	            QRgb rgb = *p++;
   516	            r_buf[ x ] = qRed(rgb);
   517	            g_buf[ x ] = qGreen(rgb);
   518	            b_buf[ x ] = qBlue(rgb);
   519	        }
   520	
   521	        writeLine(s, r_buf);
   522	        writeLine(s, g_buf);
   523	        writeLine(s, b_buf);
   524	    }
   525	}
